from pypdf import PdfReader
r=PdfReader('manuscript.pdf')
urls=set()
for p in r.pages:
    for a in p.get('/Annots',[]):
        a=a.get_object()
        act=a.get('/A')
        if act and act.get('/URI'):
            urls.add(str(act['/URI']))
for u in sorted(urls):
    if any(t in u.lower() for t in ['github','code','zenodo','osf']): print(u)
